mapper.select:
SELECT ifnull(sum(mws.check_pass_num + mws.check_ng_num), 0) as submit_num, mu.nick_name, mp.unit as unit, mu.user_name, mu.avatar FROM micro_work_submit mws LEFT JOIN micro_product mp on mws.product_seq = mp.product_seq LEFT JOIN micro_user mu on mu.id = mws.submit_user
mws.submit_status = '0'
and mws.submit_day BETWEEN #{startDate} AND #{endDate}
and mws.submit_type = #{submitType}
group by mws.created_by ORDER BY submit_num desc

SELECT mws.product_seq, mp.product_code, mp.product_name, ifnull(sum(check_pass_num + check_ng_num), 0) as finished_num, ifnull(sum(check_ng_num), 0) as ng_num, ifnull(sum(check_pass_num), 0) as pass_num, mws.operate_process_seq as process_seq, mpc.process_name, mp.unit as unit FROM micro_work_submit mws LEFT JOIN micro_product mp on mp.product_seq = mws.product_seq LEFT JOIN micro_process_common mpc on mpc.process_seq = mws.operate_process_seq WHERE mws.submit_status = '0' and mws.submit_type = '1' and mws.is_last_process = '0'
and mws.submit_day BETWEEN #{startDate} AND #{endDate}
GROUP BY mws.product_seq ORDER BY finished_num desc

select s.product_seq, d.product_code, d.product_name, d.unit as product_unit, s.process_seq, p.process_code, p.process_name, s.pass_num, s.ng_num from micro_process_storage s left join micro_process_common p on s.process_seq = p.process_seq left join micro_product d on s.product_seq = d.product_seq
and s.product_seq = #{productSeq}
order by s.pass_num + s.ng_num desc

SELECT
IFNULL(SUM(pass_num + ng_num), 0) as totalNums
FROM micro_work_submit

    and submit_type = '1'

        and submit_day BETWEEN #{startDate} and #{endDate}


        and submit_status = #{submitStatus}

SELECT IFNULL(SUM(check_pass_num + check_ng_num), 0) as total_counts, IFNULL(sum(check_pass_num),0) as total_pass_num, IFNULL(sum(check_ng_num),0) as total_ng_num FROM micro_work_submit
submit_type = '1'
and submit_day BETWEEN #{startDate} and #{endDate}
and submit_status = #{submitStatus}

SELECT a.product_seq as productSeq, a.operate_process_seq as processSeq, a.product_name as productName, a.process_name as processName, a.product_code as productCode, IFNULL(sum(a.pass_num), 0) as passNum, IFNULL(sum(a.ng_num), 0) as ngNum FROM ( SELECT mws.product_seq, mws.operate_process_seq, mp.product_name, mpc.process_name, mp.product_code, IFNULL(sum(mws.check_pass_num), 0) as pass_num, IFNULL(sum(mws.check_ng_num), 0) as ng_num FROM micro_work_submit mws INNER JOIN micro_product mp on mws.product_seq = mp.product_seq and mws.tenant_code = mp.tenant_code INNER JOIN micro_process_common mpc on mws.operate_process_seq = mpc.process_seq and mws.tenant_code = mpc.tenant_code INNER JOIN micro_user mu on mu.id = mws.submit_user
mws.submit_type = '1' and mws.submit_status = 0
and mws.product_seq in
#{productSeq}
and mu.user_name = #{userName}
and #{startDate} <= DATE_FORMAT(mws.submit_day, '%Y-%m-%d') and #{endDate} >= DATE_FORMAT(mws.submit_day, '%Y-%m-%d')
GROUP BY mws.product_seq, mws.operate_process_seq UNION ALL SELECT mws.product_seq, mws.operate_process_seq, mp.product_name, mpc.process_name, mp.product_code, IFNULL(sum(mws.pass_num), 0) as pass_num, IFNULL(sum(mws.ng_num), 0) as ng_num FROM micro_work_submit mws INNER JOIN micro_product mp on mws.product_seq = mp.product_seq and mws.tenant_code = mp.tenant_code INNER JOIN micro_process_common mpc on mws.operate_process_seq = mpc.process_seq and mws.tenant_code = mpc.tenant_code INNER JOIN micro_user mu on mu.id = mws.submit_user
mws.submit_type = '1' and mws.submit_status in (1,2)
and mws.product_seq in
#{productSeq}
and mu.user_name = #{userName}
and #{startDate} <= DATE_FORMAT(mws.submit_day, '%Y-%m-%d') and #{endDate} >= DATE_FORMAT(mws.submit_day, '%Y-%m-%d')
GROUP BY mws.product_seq, mws.operate_process_seq ) a GROUP BY a.product_seq, a.operate_process_seq
